#include <bits/stdc++.h>
using namespace std;

int main(){
    long long x;
    cin >> x;
    long long base = ((-x) % 360 + 360) % 360;
    int bestK = 0;
    long long bestDev = LLONG_MAX;
    for (int k = 0; k < 4; ++k) {
        long long total = (base + 90LL * k) % 360;
        long long dev = min(total, 360 - total);
        if (dev < bestDev) {
            bestDev = dev;
            bestK = k;
        }
    }
    cout << bestK << endl;
    return 0;
}
